14	Future<void> main() async {
15	  WidgetsFlutterBinding.ensureInitialized();
16	  try {
17	    await setupCoreDependencies();
18	  } catch (error) {
19	    debugPrint(
20	      'Cerne failed to start: could not load .env ($error). Copy '
21	      '.env.example to .env and fill in FUNCTIONS_BASE_URL + '
22	      'SUPABASE_ANON_KEY before running the app.',
23	    );
24	    rethrow;
25	  }
