29	/// Root widget. Portrait-only, light-mode-only, fixed 390x844 frame — no
30	/// breakpoint, landscape or dark-mode path anywhere in the app (per the
31	/// epic's UX constraints).
32	///
33	/// Story 1.4 scope: `home` branches on `SessionRepository.statusStream`
34	/// instead of hardcoding `AuthScreen` — `restoreSession()` fires once at
35	/// boot (unconditional, no client-side expiry math) and the stream's first
36	/// emission decides whether the user lands on `AuthScreen` or the post-auth
37	/// placeholder. No `go_router` yet (Story 1.6): the `MaterialApp`/`Navigator`
38	/// shape is unchanged, and a successful signup/login still simply
39	/// pushes-replaces via `onAuthenticated`.
40	class CerneApp extends StatefulWidget {
41	  const CerneApp({super.key});
42	
43	  @override
44	  State<CerneApp> createState() => _CerneAppState();
45	}
46	
47	class _CerneAppState extends State<CerneApp> {
48	  late final SessionRepository _sessionRepository;
49	
50	  // Cached once: `SessionRepository.statusStream`'s getter builds a new
51	  // `Stream.multi` instance on every access (code review of
52	  // story-1-4-silent-session-refresh-persistence), so reading it straight
53	  // into `StreamBuilder.stream` on every `build()` would make it resubscribe
54	  // and lose its current status on each rebuild instead of staying on one
55	  // subscription for this widget's lifetime.
56	  late final Stream<SessionStatus> _statusStream;
57	
58	  @override
59	  void initState() {
60	    super.initState();
61	    _sessionRepository = sl<SessionRepository>();
62	    _statusStream = _sessionRepository.statusStream;
63	    // Fire-and-forget: the outcome reaches the UI through `statusStream`
64	    // below, not through this call's return value. `restoreSession()`
65	    // already maps every internal failure to `Left`/an `unauthenticated`
66	    // emission and never throws. This `catchError` is NOT a UI recovery
67	    // path — its handler's return value is discarded by `unawaited` and
68	    // never reaches `statusStream`, so it does not unblock `build()`'s
69	    // `_BootLoadingScreen` branch. It exists purely so a future regression
70	    // that broke the "never throws" contract above would surface as a
71	    // logged message instead of an unhandled zone exception.
72	    unawaited(
73	      _sessionRepository.restoreSession().catchError(_asUnauthenticated),
74	    );
75	  }
76	
77	  // `catchError`'s handler must still complete the Future with a value of
78	  // its declared type (`Either<Failure, Unit>`) — a `void`-returning
79	  // handler would try to complete it with `null`, which isn't assignable
80	  // to that non-nullable type and would itself throw.
81	  static Either<Failure, Unit> _asUnauthenticated(
82	    Object error,
83	    StackTrace stackTrace,
84	  ) {
85	    debugPrint('CerneApp: restoreSession() threw unexpectedly ($error)');
86	    return left(Failure.malformedResponse(message: error.toString()));
87	  }
88	
89	  @override
90	  Widget build(BuildContext context) {
91	    return MaterialApp(
92	      debugShowCheckedModeBanner: false,
93	      home: StreamBuilder<SessionStatus>(
94	        stream: _statusStream,
95	        builder: (context, snapshot) {
96	          if (!snapshot.hasData) {
97	            // No emission yet: brief-blank for the happy path (RNF01's
98	            // 300ms threshold) — `_BootLoadingScreen` only surfaces a
99	            // spinner once the wait actually crosses that.
100	            return const _BootLoadingScreen();
101	          }
102	          if (snapshot.data == SessionStatus.authenticated) {
103	            return const _PostAuthPlaceholder();
104	          }
105	          return AuthScreen(
106	            cubit: sl<AuthCubit>(),
107	            onAuthenticated: (context) => Navigator.of(context).pushReplacement(
108	              MaterialPageRoute(builder: (_) => const _PostAuthPlaceholder()),
109	            ),
110	          );
111	        },
112	      ),
113	    );
114	  }
115	}
