134	/// Shown while `statusStream` has no data yet. Blank for the happy path
135	/// (RNF01: no loading UI below 300ms), but surfaces a centered spinner once
136	/// the wait crosses that threshold — `auth-refresh` is retried by
137	/// `RetryInterceptor` on `NETWORK_TIMEOUT`/`NETWORK_OFFLINE`, so a slow or
138	/// offline boot could otherwise leave the screen looking frozen for several
139	/// seconds with zero feedback. Kept as a private, inline, one-off widget
140	/// (no new shared-widget param) — same minimal-treatment convention Story
141	/// 1.3's submit button uses for its own >300ms affordance.
142	class _BootLoadingScreen extends StatefulWidget {
143	  const _BootLoadingScreen();
144	
145	  @override
146	  State<_BootLoadingScreen> createState() => _BootLoadingScreenState();
147	}
148	
149	class _BootLoadingScreenState extends State<_BootLoadingScreen> {
150	  static const _threshold = Duration(milliseconds: 300);
151	
152	  bool _showIndicator = false;
153	  Timer? _timer;
154	
155	  @override
156	  void initState() {
157	    super.initState();
158	    _timer = Timer(_threshold, () {
159	      if (mounted) {
160	        setState(() => _showIndicator = true);
161	      }
162	    });
163	  }
164	
165	  @override
166	  void dispose() {
167	    _timer?.cancel();
168	    super.dispose();
169	  }
170	
171	  @override
172	  Widget build(BuildContext context) {
173	    return Scaffold(
174	      backgroundColor: DesignTokens.colorSurfaceBg,
175	      body: Center(
176	        child: _showIndicator
177	            ? const CircularProgressIndicator(color: DesignTokens.colorPrimary)
178	            : const SizedBox.shrink(),
179	      ),
180	    );
181	  }
182	}
