2	// from the private fields they initialize, so an initializing formal
3	// (which would force the external name to match) isn't a clean fit here.
4	// ignore_for_file: prefer_initializing_formals
5	import 'package:dio/dio.dart';
6	import 'package:fpdart/fpdart.dart';
7	
8	import '../failure/failure.dart';
9	import 'dio_error_code.dart';
10	import 'url_builder.dart';
11	
12	/// AD-2/AD-5 — the one network façade every repository's data source calls
13	/// through. Builds the real URL via `UrlBuilder`, sends the request through
14	/// `dio` (header + retry interceptors already attached in DI), and maps
15	/// every outcome — success or failure — to `Either<Failure, T>`; no
16	/// dio/native exception ever escapes unmapped (RNF09).
17	///
18	/// Tests mock this interface directly (per the architecture spine's testing
19	/// convention), not a fake transport layer underneath it.
20	class ApiClient {
21	  ApiClient({required Dio dio, required UrlBuilder urlBuilder})
22	      : _dio = dio,
23	        _urlBuilder = urlBuilder;
24	
25	  final Dio _dio;
26	  final UrlBuilder _urlBuilder;
27	
28	  Future<Either<Failure, Map<String, dynamic>>> get(
29	    String function, {
30	    List<String> pathParams = const [],
31	    Map<String, dynamic>? queryParameters,
32	  }) =>
33	      _send(
34	        () => _dio.get<Map<String, dynamic>>(
35	          _urlBuilder.build(function, pathParams),
36	          queryParameters: queryParameters,
37	        ),
38	      );
39	
40	  Future<Either<Failure, Map<String, dynamic>>> post(
41	    String function, {
42	    List<String> pathParams = const [],
43	    Object? data,
44	  }) =>
45	      _send(
46	        () => _dio.post<Map<String, dynamic>>(
47	          _urlBuilder.build(function, pathParams),
48	          data: data,
49	        ),
50	      );
51	
52	  Future<Either<Failure, Map<String, dynamic>>> patch(
53	    String function, {
54	    List<String> pathParams = const [],
55	    Object? data,
56	  }) =>
57	      _send(
58	        () => _dio.patch<Map<String, dynamic>>(
59	          _urlBuilder.build(function, pathParams),
60	          data: data,
61	        ),
62	      );
63	
64	  Future<Either<Failure, Map<String, dynamic>>> delete(
65	    String function, {
66	    List<String> pathParams = const [],
67	    Object? data,
68	  }) =>
69	      _send(
70	        () => _dio.delete<Map<String, dynamic>>(
71	          _urlBuilder.build(function, pathParams),
72	          data: data,
73	        ),
74	      );
75	
76	  Future<Either<Failure, Map<String, dynamic>>> _send(
77	    Future<Response<Map<String, dynamic>>> Function() request,
78	  ) async {
79	    try {
80	      final response = await request();
81	      final data = response.data;
82	      if (data == null) {
83	        return left(
84	          const Failure.malformedResponse(message: 'Empty response body'),
85	        );
86	      }
87	      return right(data);
88	    } on DioException catch (e) {
89	      return left(_mapDioException(e));
90	    } catch (e) {
91	      return left(Failure.malformedResponse(message: e.toString()));
92	    }
93	  }
94	
95	  Failure _mapDioException(DioException e) {
96	    final code = dioErrorCodeOf(e);
97	    if (code == null) {
98	      // Covers a cancelled request and an HTTP response that doesn't carry
99	      // the expected `{code, message, retryable}` body — neither is one of
100	      // the 13 backend codes, so neither is retryable (dioErrorCodeOf).
101	      return Failure.malformedResponse(
102	        message: e.message ?? 'Malformed response',
103	      );
104	    }
105	    final data = e.response?.data;
106	    final message = data is Map ? data['message'] : null;
107	    return Failure.fromCode(
108	      code,
109	      (message is String ? message : null) ?? e.message ?? 'Unknown error',
110	    );
111	  }
112	}
