15	/// Owns the one broadcast [SessionStatus] stream the epic's AD requires.
16	/// [restoreSession] is unconditional — no client-side expiry math — and
17	/// covers the I/O matrix (spec-1-4):
18	/// - no stored refresh token -> no network call, emits `unauthenticated`
19	///   immediately.
20	/// - stored token, backend accepts -> new pair persisted via `saveSession`,
21	///   emits `authenticated`.
22	/// - stored token, backend reports `AUTH_EXPIRED`/`AUTH_INVALID` (dead
23	///   token) -> `clearSession`, emits `unauthenticated`.
24	/// - stored token, any other failure (offline/timeout/...) -> fail-closed:
25	///   emits `unauthenticated` WITHOUT clearing storage, so the next boot
26	///   retries naturally.
27	class SessionRepositoryImpl implements SessionRepository {
28	  SessionRepositoryImpl({
29	    required AuthRemoteDataSource remoteDataSource,
30	    required AccessTokenProvider accessTokenProvider,
31	  }) : _remoteDataSource = remoteDataSource,
32	       _accessTokenProvider = accessTokenProvider;
33	
34	  final AuthRemoteDataSource _remoteDataSource;
35	  final AccessTokenProvider _accessTokenProvider;
36	  final StreamController<SessionStatus> _statusController =
37	      StreamController<SessionStatus>.broadcast();
38	
39	  /// The last status emitted, so a consumer that subscribes *after* the
40	  /// first emission (a later `StreamBuilder`, or Story 1.5/1.6's own
41	  /// listener) still sees current state immediately rather than nothing
42	  /// until the next change — see [statusStream].
43	  SessionStatus? _lastStatus;
44	
45	  @override
46	  Stream<SessionStatus> get statusStream {
47	    // `Stream.multi` runs this callback once per listener (and, with
48	    // `isBroadcast: true`, supports more than one simultaneously) — each
49	    // new listener synchronously gets the cached last status (if any)
50	    // before being attached to the live broadcast controller for whatever
51	    // comes next. This is this story's whole reason to not just expose
52	    // `_statusController.stream` directly: a plain broadcast stream only
53	    // ever delivers *future* events to a listener that joins late.
54	    return Stream<SessionStatus>.multi((controller) {
55	      final last = _lastStatus;
56	      if (last != null) {
57	        controller.add(last);
58	      }
59	      final subscription = _statusController.stream.listen(
60	        controller.add,
61	        onError: controller.addError,
62	        onDone: controller.close,
63	      );
64	      controller.onCancel = subscription.cancel;
65	    }, isBroadcast: true);
66	  }
67	
68	  void _emit(SessionStatus status) {
69	    // Guards against `dispose()` (wired to `get_it`'s `sl.reset()`) racing
70	    // an in-flight `restoreSession()` call — without this, a late `.add()`
71	    // after `.close()` would throw an unhandled `StateError` instead of
72	    // just being a no-op on an already-torn-down repository.
73	    if (_statusController.isClosed) {
74	      return;
75	    }
76	    _lastStatus = status;
77	    _statusController.add(status);
78	  }
79	
80	  @override
81	  Future<Either<Failure, Unit>> restoreSession() async {
82	    String? refreshToken;
83	    try {
84	      refreshToken = await _accessTokenProvider.readRefreshToken();
85	    } catch (error) {
86	      // A thrown platform exception from the native secure-storage channel
87	      // must never escape unmapped (RNF09) — fail closed, same as any other
88	      // unreadable session.
89	      _emit(SessionStatus.unauthenticated);
90	      return left(Failure.malformedResponse(message: error.toString()));
91	    }
92	
93	    if (refreshToken == null || refreshToken.isEmpty) {
94	      // Fresh install / post-logout (null), or a stored-but-empty token
95	      // (the backend response schema has no `minLength` on `refreshToken`,
96	      // so an empty string is a theoretically valid stored value) — either
97	      // way, no network call: `auth-refresh`'s own request schema requires
98	      // `minLength: 1`, so an empty token would only fail server-side.
99	      _emit(SessionStatus.unauthenticated);
100	      return left(
101	        const Failure.authExpired(message: 'No stored session to restore'),
102	      );
103	    }
104	
105	    final result = await _remoteDataSource.refresh(refreshToken);
106	    return result.match(
107	      (failure) async {
108	        // Only a backend-confirmed dead token clears storage; any other
109	        // failure (offline, timeout, malformed response, ...) leaves it
110	        // untouched so the next boot retries naturally.
111	        if (failure is AuthExpired || failure is AuthInvalid) {
112	          try {
113	            await _accessTokenProvider.clearSession();
114	          } catch (_) {
115	            // Best-effort clear — the session is already being treated as
116	            // unauthenticated below regardless of whether this succeeds.
117	          }
118	        }
119	        _emit(SessionStatus.unauthenticated);
120	        return left(failure);
121	      },
122	      (session) async {
123	        try {
124	          await _accessTokenProvider.saveSession(
125	            accessToken: session.accessToken,
126	            refreshToken: session.refreshToken,
127	          );
128	        } catch (error) {
129	          _emit(SessionStatus.unauthenticated);
130	          return left(Failure.malformedResponse(message: error.toString()));
131	        }
132	        _emit(SessionStatus.authenticated);
133	        return right(unit);
134	      },
135	    );
136	  }
137	
138	  @override
139	  Future<void> dispose() => _statusController.close();
140	}
